1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../domain/entities/chat_message.dart';
8	import '../../domain/entities/chat_session.dart';
9	import '../../domain/entities/chat_stream_event.dart';
10	import '../../domain/repositories/chat_repository.dart';
11	import 'chat_state.dart';
12	
13	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
14	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
15	/// same app session never re-bootstraps the session/history it already
16	/// loaded (`init()`'s own no-op guard below).
17	class ChatCubit extends Cubit<ChatState> {
18	  ChatCubit(this._repository) : super(const ChatBootstrapLoading());
19	
20	  final ChatRepository _repository;
21	
22	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
23	
24	  /// The in-flight [sendMessage]'s own completer, if any — [close] must
25	  /// complete it itself, since cancelling [_sendSubscription] never fires
26	  /// `onDone`/`onError` (review fix: `cancel()` alone left `sendMessage()`'s
27	  /// returned `Future` permanently unresolved when the cubit closed mid-send).
28	  Completer<void>? _sendCompleter;
29	
30	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
31	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
32	  /// own doc on why `message_created`'s id goes unused here).
33	  int _localIdCounter = 0;
34	
35	  /// Whether a send is actively in flight right now — tracked locally
36	  /// rather than by scanning [ChatState.messages] for a persisted
37	  /// `streaming` status, since a message loaded from history/cache can
38	  /// legitimately carry that same status (e.g. one left over from an
39	  /// earlier dropped response, the I/O matrix's own scenario) without a
40	  /// send actually being in progress; scanning for it would permanently
41	  /// disable the composer in that case.
42	  bool _isSending = false;
43	
44	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
45	  /// instead of starting a second bootstrap, so two near-simultaneous
46	  /// callers (e.g. two mounts before the first resolves) never both
47	  /// observe "no sessions" and both call `createSession()` (Boundaries:
48	  /// "silently ensure *one* Chat Session exists").
49	  Future<void>? _initFuture;
50	
51	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
52	  /// exists (reuse the most recent from `chat-sessions-list`, else
53	  /// `chat-sessions-create` with no title)". A no-op once already
54	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
55	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
56	  /// from an earlier visit.
57	  Future<void> init() {
58	    if (state is ChatReady || isClosed) {
59	      return Future.value();
60	    }
61	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
62	  }
63	
64	  Future<void> _bootstrap() async {
65	    emit(const ChatBootstrapLoading());
66	
67	    final sessionsResult = await _repository.listSessions();
68	    if (isClosed) {
69	      return;
70	    }
71	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
72	        .match((failure) async => left(failure), (sessions) async {
73	          if (sessions.isEmpty) {
74	            return _repository.createSession();
75	          }
76	          // "reuse the most recent" — defensively re-sorts rather than
77	          // trusting `listSessions()`'s own ordering (its offline-cache
78	          // fallback already sorts `updatedAt` desc, but the live
79	          // server response's own ordering isn't documented either
80	          // way).
81	          final mostRecent = [...sessions]..sort(
82	            (a, b) => DateTime.parse(
83	              b.updatedAt,
84	            ).compareTo(DateTime.parse(a.updatedAt)),
85	          );
86	          return right(mostRecent.first);
87	        });
88	    if (isClosed) {
89	      return;
90	    }
91	
92	    await sessionResult.match(
93	      (failure) async {
94	        if (!isClosed) {
95	          emit(ChatBootstrapError(failure));
96	        }
97	      },
98	      (session) async {
99	        final messagesResult = await _repository.listMessages(session.id);
100	        if (isClosed) {
101	          return;
102	        }
103	        messagesResult.match(
104	          (failure) => emit(ChatBootstrapError(failure)),
105	          (messages) => emit(
106	            ChatReady(
107	              sessionId: session.id,
108	              messages: messages.map(_fromDomain).toList(),
109	            ),
110	          ),
111	        );
112	      },
113	    );
114	  }
115	
116	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
117	    id: message.id,
118	    role: message.role,
119	    content: message.content,
120	    status: message.status,
121	  );
122	
123	  /// Boundaries: optimistic user bubble, then subscribes to
124	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
125	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
126	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
127	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
128	  ///
129	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
130	  /// or failed — the composer is disabled in that case anyway), while
131	  /// [content] is blank once trimmed, or while [_isSending] is already
132	  /// true — this story never races two concurrent sends against the one
133	  /// in-memory session (Boundaries: no offline lock/composer-disable UI
134	  /// of its own exists yet, Story 6.3's job, so this guard is the one
135	  /// thing standing in for it here). Deliberately not keyed off any
136	  /// loaded message's persisted `streaming` status — a message restored
137	  /// from history/cache can legitimately carry that status without a
138	  /// send actually being in flight (I/O matrix: mid-stream drop).
139	  Future<void> sendMessage(String content) async {
140	    final trimmed = content.trim();
141	    if (trimmed.isEmpty) {
142	      return;
143	    }
144	    final current = state;
145	    if (current is! ChatReady) {
146	      return;
147	    }
148	    if (_isSending) {
149	      return;
150	    }
151	    _isSending = true;
152	
153	    final userMessage = ChatUiMessage(
154	      id: _nextLocalId(),
155	      role: ChatMessageRole.user,
156	      content: trimmed,
157	      status: ChatMessageStatus.complete,
158	    );
159	    final aiMessage = ChatUiMessage(
160	      id: _nextLocalId(),
161	      role: ChatMessageRole.assistant,
162	      content: '',
163	      status: ChatMessageStatus.streaming,
164	    );
165	    emit(
166	      current.copyWith(
167	        messages: [...current.messages, userMessage, aiMessage],
168	        isSending: true,
169	      ),
170	    );
171	
172	    await _sendSubscription?.cancel();
173	    final completer = Completer<void>();
174	    _sendCompleter = completer;
175	    _sendSubscription = _repository
176	        .sendMessage(current.sessionId, trimmed)
177	        .listen(
178	          (event) {
179	            event.match(
180	              (failure) => _markFailed(aiMessage.id),
181	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
182	            );
183	          },
184	          onError: (Object _, StackTrace _) {
185	            // RNF09: no exception escapes the cubit — a stream-level
186	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
187	            // never lets one through unmapped) still only fails the
188	            // bubble, never crashes.
189	            _markFailed(aiMessage.id);
190	            _finishSending();
191	            if (!completer.isCompleted) {
192	              completer.complete();
193	            }
194	            _sendCompleter = null;
195	          },
196	          onDone: () {
197	            _finishSending();
198	            if (!completer.isCompleted) {
199	              completer.complete();
200	            }
201	            _sendCompleter = null;
202	          },
203	          cancelOnError: false,
204	        );
205	    await completer.future;
206	  }
207	
208	  /// Clears both the internal re-entrancy guard and the UI-facing
209	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
210	  /// an in-band error, or a stream-level error) — the single place both
211	  /// flip back together.
212	  void _finishSending() {
213	    _isSending = false;
214	    if (isClosed) {
215	      return;
216	    }
217	    final current = state;
218	    if (current is ChatReady) {
219	      emit(current.copyWith(isSending: false));
220	    }
221	  }
222	
223	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
224	    if (isClosed) {
225	      return;
226	    }
227	    final current = state;
228	    if (current is! ChatReady) {
229	      return;
230	    }
231	    switch (event) {
232	      case ChatMessageCreatedEvent():
233	        // Design Notes: the persisted *user*-message id — no UI-facing
234	        // use yet in this story (Story 6.3's retry call is the first
235	        // consumer).
236	        break;
237	      case ChatTokenEvent(delta: final delta):
238	        emit(
239	          current.copyWith(
240	            messages: [
241	              for (final message in current.messages)
242	                if (message.id == aiMessageId)
243	                  message.copyWith(content: message.content + delta)
244	                else
245	                  message,
246	            ],
247	          ),
248	        );
249	      case ChatDoneEvent():
250	        emit(
251	          current.copyWith(
252	            messages: [
253	              for (final message in current.messages)
254	                if (message.id == aiMessageId)
255	                  message.copyWith(status: ChatMessageStatus.complete)
256	                else
257	                  message,
258	            ],
259	          ),
260	        );
261	    }
262	  }
263	
264	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
265	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
266	  /// as-is (never cleared, Boundaries).
267	  void _markFailed(String aiMessageId) {
268	    if (isClosed) {
269	      return;
270	    }
271	    final current = state;
272	    if (current is! ChatReady) {
273	      return;
274	    }
275	    emit(
276	      current.copyWith(
277	        messages: [
278	          for (final message in current.messages)
279	            if (message.id == aiMessageId)
280	              message.copyWith(status: ChatMessageStatus.failed)
281	            else
282	              message,
283	        ],
284	      ),
285	    );
286	  }
287	
288	  String _nextLocalId() => 'local-${_localIdCounter++}';
289	
290	  @override
291	  Future<void> close() {
292	    _sendSubscription?.cancel();
293	    final completer = _sendCompleter;
294	    if (completer != null && !completer.isCompleted) {
295	      completer.complete();
296	    }
297	    _sendCompleter = null;
298	    return super.close();
299	  }
300	}
