85	  @override
86	  Future<Either<Failure, List<Entry>>> search(
87	    String query, {
88	    EntrySource? source,
89	    DateTime? dateFrom,
90	    DateTime? dateTo,
91	  }) async => throw UnimplementedError('not expected to be called');
