158	/// A plain (non-mocktail) fake — the redirect matrix needs [currentStatus]
159	/// read synchronously right after [setStatus], and `statusStream` to
160	/// actually emit so `GoRouterRefreshStream` re-triggers `redirect`; a
161	/// mocktail stub can't do both at once as naturally as this tiny fake.
162	class _FakeSessionRepository implements SessionRepository {
163	  SessionStatus? _status;
164	  final _controller = StreamController<SessionStatus>.broadcast();
165	
166	  @override
167	  SessionStatus? get currentStatus => _status;
168	
169	  @override
170	  Stream<SessionStatus> get statusStream => _controller.stream;
171	
172	  @override
173	  Future<Either<Failure, Unit>> restoreSession() async => right(unit);
174	
175	  @override
176	  void markAuthenticated() => setStatus(SessionStatus.authenticated);
177	
178	  @override
179	  Future<void> dispose() => _controller.close();
180	
181	  void setStatus(SessionStatus status) {
182	    _status = status;
183	    _controller.add(status);
184	  }
185	}
