187	/// A plain (non-mocktail) fake for [VaultRepository], same rationale as
188	/// [_FakeSessionRepository] above — defaults to [VaultStatus.unlocked] so
189	/// every pre-existing (Story 1.6) test case is unaffected by AD-14's new
190	/// gate unless a test explicitly locks it.
191	class _FakeVaultRepository implements VaultRepository {
192	  VaultStatus _status = VaultStatus.unlocked;
193	  final _controller = StreamController<VaultStatus>.broadcast();
194	
195	  /// Controls what [authenticate] resolves to. Defaults to `false` (a
196	  /// quiet failure) so that mounting `VaultLockScreen` in a test — which
197	  /// auto-calls [authenticate] once in `initState` — never silently
198	  /// unlocks the vault on its own; [setStatus] stays the single, explicit
199	  /// way a test flips vault state.
200	  bool authenticateSucceeds = false;
201	
202	  @override
203	  VaultStatus get currentStatus => _status;
204	
205	  @override
206	  Stream<VaultStatus> get statusStream => _controller.stream;
207	
208	  @override
209	  Future<Either<Failure, Unit>> authenticate() async {
210	    if (authenticateSucceeds) {
211	      setStatus(VaultStatus.unlocked);
212	      return right(unit);
213	    }
214	    return left(
215	      const Failure.malformedResponse(message: 'fake: biometrics declined'),
216	    );
217	  }
218	
219	  /// Not exercised by this router-focused suite (spec-2-2's PIN flow has
220	  /// its own dedicated coverage in `vault_lock_screen_test.dart`) — always
221	  /// fails, so a stray call here never silently unlocks the vault.
222	  @override
223	  Future<Either<Failure, Unit>> submitPin(String pin) async {
224	    return left(const Failure.malformedResponse(message: 'fake: unused'));
225	  }
226	
227	  @override
228	  Future<void> dispose() => _controller.close();
229	
230	  void setStatus(VaultStatus status) {
231	    _status = status;
232	    _controller.add(status);
233	  }
234	}
