236	/// A plain (non-mocktail) fake for [AccountSettingsRepository] (Story 2.4,
237	/// AD-14-style seam) — same rationale as [_FakeSessionRepository]/
238	/// [_FakeVaultRepository]. Defaults to `true` (never `null`), matching
239	/// [AccountSettingsRepository.currentBiometricEnabled]'s own documented
240	/// default.
241	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
242	  bool _value = true;
243	  final _controller = StreamController<bool>.broadcast();
244	
245	  @override
246	  bool get currentBiometricEnabled => _value;
247	
248	  @override
249	  Stream<bool> get biometricEnabledStream => _controller.stream;
250	
251	  @override
252	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
253	
254	  @override
255	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
256	    setValue(enabled);
257	    return right(unit);
258	  }
259	
260	  @override
261	  Future<void> dispose() => _controller.close();
262	
263	  void setValue(bool value) {
264	    _value = value;
265	    _controller.add(value);
266	  }
267	}
