269	/// Proves the epic's ONE `GoRouter`/`redirect` (Boundaries) resolves the
270	/// I/O & Edge-Case Matrix from spec-1-6/spec-2-1 exactly — composing
271	/// [VaultStatus] first, then [SessionStatus] (AD-14), never a hardcoded
272	/// assumption baked into either matrix.
273	void main() {
274	  late _FakeSessionRepository fakeSessionRepository;
275	  late _FakeVaultRepository fakeVaultRepository;
276	  late _FakeAccountSettingsRepository fakeAccountSettingsRepository;
277	
278	  setUp(() {
279	    fakeSessionRepository = _FakeSessionRepository();
280	    fakeVaultRepository = _FakeVaultRepository();
281	    fakeAccountSettingsRepository = _FakeAccountSettingsRepository();
282	    // `/auth`'s `GoRoute.builder` resolves `sl<AuthCubit>()` — registered
283	    // directly (no full `setupCoreDependencies()`) since this suite only
284	    // exercises the router, not the auth call itself.
285	    final mockSessionRepositoryForCubit = MockSessionRepository();
286	    when(() => mockSessionRepositoryForCubit.markAuthenticated())
287	        .thenReturn(null);
288	    sl.registerLazySingleton<AuthCubit>(
289	      () => AuthCubit(MockAuthRepository(), mockSessionRepositoryForCubit),
290	    );
291	    // `/configuracoes`'s `GoRoute.builder` resolves `sl<AccountSettingsCubit>
292	    // ()` (Story 2.4) — same rationale as `AuthCubit` above, wired to the
293	    // same fake repository `pumpRouter` passes into `buildAppRouter` so a
294	    // test can also drive it through the cubit if ever needed.
295	    sl.registerLazySingleton<AccountSettingsCubit>(
296	      () => AccountSettingsCubit(fakeAccountSettingsRepository),
