24	/// A controllable fake — this suite drives `sendMessage`'s own SSE-shaped
25	/// stream event by event (rather than mocktail-stubbing a fixed `Stream`),
26	/// so each test can assert the cubit's state *between* events (e.g. right
27	/// after one `token` but before `done`).
28	class _FakeChatRepository implements ChatRepository {
29	  Either<Failure, List<ChatSession>> listSessionsResult = right([_session]);
30	  Either<Failure, ChatSession> createSessionResult = right(_session);
31	  Either<Failure, List<ChatMessage>> listMessagesResult = right(const []);
32	
33	  StreamController<Either<Failure, ChatStreamEvent>>? lastSendController;
34	  final List<({String sessionId, String content})> sendMessageCalls = [];
35	
36	  @override
37	  Future<Either<Failure, List<ChatSession>>> listSessions() async =>
38	      listSessionsResult;
39	
40	  @override
41	  Future<Either<Failure, ChatSession>> createSession() async =>
42	      createSessionResult;
43	
44	  @override
45	  Future<Either<Failure, List<ChatMessage>>> listMessages(
46	    String sessionId,
47	  ) async => listMessagesResult;
48	
49	  @override
50	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
51	    String sessionId,
52	    String content,
53	  ) {
54	    sendMessageCalls.add((sessionId: sessionId, content: content));
55	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
56	    lastSendController = controller;
57	    return controller.stream;
58	  }
59	}
